Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Record gvp : Type := mk_gvp { gv_D : Z; gv_N : Z; gv_w : Z; gv_h : Z; gv_wpl : Z }.
Definition gv_ok (p : gvp) : Prop :=
  0 < gv_w p <= 20000 /\ 0 < gv_h p <= 20000 /\ gv_wpl p = (gv_w p * 8 + 31) / 32 /\ gv_N p = 4 * (gv_wpl p * gv_h p)
  /\ 0 < gv_N p <= 0x4000000
  /\ 0 < gv_D p /\ gv_D p mod 16 = 0 /\ gv_D p + gv_N p <= 2^47 /\ (gv_D p + gv_N p <= 0x7fff7000 \/ 0x10007fff8000 <= gv_D p)
  /\ (gv_D p + gv_N p <= 0x10000 \/ 0x642000 <= gv_D p).
(* [comment removed for export] *)
Definition gv_e (ty e : Z) : Prop := 0 <= e <= 255 \/ (ty = L_SELECT_MIN /\ e = 100000) \/ (ty = L_SELECT_MAX /\ e = -1).

