(* [comment removed for export] *)
Definition gv_i_exit (p : gvp) (rf : Z) (ra sp gp tp s0 a3 s2 s9 s10 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (t2' a0' a1' a4' s3' s6' s7' s8' s11' t3' t4' t5' t6' : word) (e' : Z),
    ms' = MS (mkR ra sp gp tp (Z_to_bv 64 1) (Z_to_bv 64 3) t2' s0 (Z_to_bv 64 rf) a0' a1' (Z_to_bv 64 e') a3 a4' (Z_to_bv 64 (gv_wpl p)) (Z_to_bv 64 (gv_h p)) (Z_to_bv 64 1)
                  s2 s3' (Z_to_bv 64 2147450880) (Z_to_bv 64 1) s6' s7' s8' s9 s10 s11' t3' t4' t5' t6')
             F (Z_to_bv 64 0xa563c) fc None m (seg_rom asegs)
    /\ 0 <= e' <= 255.

(* [comment removed for export] *)
Lemma gv_i_loop : forall (n : nat) (p : gvp) (ty : Z) (rf pw i e : Z)
    (ra sp gp tp t2 s0 a0 a1 a3 s2 s3 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = gv_h p - i -> 0 <= i -> (1 <= n)%nat -> gv_ok p -> (ty = L_SELECT_MIN \/ ty = L_SELECT_MAX) -> gv_e ty e ->
  0 < rf -> rf mod 32 = 0 -> rf + 192 <= 2^47 ->
  rw_cells asegs m (rf + 8) [C8 (Z_to_bv 64 (gv_h p)); C8 (Z_to_bv 64 (gv_wpl p)); C8 (Z_to_bv 64 pw); C8 (Z_to_bv 64 (gv_D p))] ->
  rw_cells asegs m (rf + 56) [C8 (Z_to_bv 64 ty)] ->
  0 < pw -> pw mod 4 = 0 -> pw + 4 <= 2^47 -> rw_cells asegs m pw [C4 (Z_to_bv 64 (gv_w p))] ->
  wr_at asegs m (gv_D p) (gv_N p) -> acc asegs m (gv_D p) (gv_N p) -> mem_inv asegs m ->
  evt asegs (gv_i_exit p rf ra sp gp tp s0 a3 s2 s9 s10 F fc m)
    (MS (mkR ra sp gp tp (Z_to_bv 64 1) (Z_to_bv 64 3) t2 s0 (Z_to_bv 64 rf) a0 a1 (Z_to_bv 64 e) a3 (Z_to_bv 64 (i * gv_wpl p)) (Z_to_bv 64 (gv_wpl p)) (Z_to_bv 64 i) (Z_to_bv 64 1)
             s2 s3 (Z_to_bv 64 2147450880) (Z_to_bv 64 1) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0xa5510) fc None m (seg_rom asegs)).
